'use strict';
/*
 * hdc-bridge-assets.js —— 生成文件，**勿手改**
 * 由 tools/embed-hdc-bridge.mjs 从 Common/dsh-hdc-bridge/ 读取并内嵌；
 * 改桥脚本后重跑：node tools/embed-hdc-bridge.mjs
 * 一致性门禁：node tools/check-hdc-bridge-embed.mjs
 */
module.exports = {
  "bridge.sh": "#!/system/bin/sh\n# ============================================================\n# hdc-bridge：在 DSHM(Whale) 应用沙箱内打通 hdc 全链路\n# 发现日期：2026-10-06 · 详见同目录 README.md\n#\n# 解决的问题：沙箱里 hdc 所有命令静默无输出（server 子进程必崩）\n# 破解三层：\n#   A. LD_PRELOAD 拦截 bind/connect/chmod/stat/unlink，\n#      把系统侧 UDS 路径重写到可写目录          -> shim.so\n#   B. 伪造 HUKS 凭据服务（ENCRYPT/DECRYPT 文本协议）-> fakecred.py\n#   C. 恢复已授权密钥 keys/hdckey.{pub,key}      -> 免二次确认弹窗\n#\n# 结果：hdc shell = uid 2000 / u:r:sh:s0；bm/hilog/file/install 全可用\n# 限制：smode root 不可用（const.debuggable=0）\n#\n# 2026-10-28 修复（根因见同目录《2026-10-28-hdc桥失效排查*.md》）：\n#  1) brew 的 ohos-sdk-toolchains 26.0.0.38 版 hdc，其 UDS bind 不再经过可被\n#     LD_PRELOAD 拦截的 libc bind（实测 shim 只收到 access、收不到 bind）⇒ 真 hdc\n#     优先用系统 hnp(hmos-clt) 自带的 SDK hdc（实测可注入）；候选逐个探测，\n#     以\"server socket 是否真的建出来\"为判据，并缓存到 $T/real.path。\n#  2) brew 的 clang 链接时 lld 报 \"Error loading shared library libxml2.so.16\"：\n#     lld 的 RUNPATH 只有 $ORIGIN/../lib、llvm/lib 里 libxml2.so.16 也在，但本机 musl\n#     在这份 lld 上没把它解析出来（机制未定论；同布局的自编程序正常）⇒ 编译 shim.so 时\n#     用 clang -print-prog-name=ld.lld 推出 llvm/lib 显式放进 LD_LIBRARY_PATH 作兜底。\n#     根治见 tools/fix-brew-llvm-rpath.sh（改 ld.lld wrapper，brew 升级后重跑）。\n#  3) 构建产物/pid 从 $TMPDIR/cache 挪到 $HOME/.hdc-bridge：cache 会被系统清，\n#     清掉就要重编译；以前一清缓存桥必挂。\n#  4) 修 hdcb 里 D 为空（heredoc 原样写出 \"${D}\"）导致自愈 `sh $D/bridge.sh`\n#     只在 cwd=本目录时才生效的隐患；hdcb/hdc 带版本标记，标记不符即重建。\n# ============================================================\nD=\"$(dirname \"$0\")\"\ncase \"$D\" in /*) ;; *) D=\"$(pwd)/$D\";; esac   # 保证绝对路径\nH=\"$HOME\"\nT=\"$H/.hdc-bridge\"        # 构建产物/状态：稳定目录（$TMPDIR 下会被系统清缓存）\nSHIMDIR=\"$H/tmp\"          # socket 落点：与 shim.c 里硬编码的 SHIMDIR 一致\nSERVER_SOCK=\"$SHIMDIR/hdcshim_hdc_server\"\nCRED_SOCK=\"$SHIMDIR/hdcshim_hdc_credential.socket\"\nBREW_HDC=\"/storage/Users/currentUser/.harmonybrew/bin/hdc\"   # brew 版（新版本不可注入，兜底）\nmkdir -p \"$T\" \"$SHIMDIR\"\n# v3.1 环境读数：这三个缺任何一个都会让\"起桥\"静默失败，先写进日志再动手\necho \"[env] HOME=$HOME\"\necho \"[env] setsid=$(command -v setsid 2>/dev/null || echo MISSING) nohup=$(command -v nohup 2>/dev/null || echo MISSING) clang=$(command -v clang 2>/dev/null || echo MISSING) python3=$(command -v python3 2>/dev/null || echo MISSING) timeout=$(command -v timeout 2>/dev/null || echo MISSING)\"\necho \"[env] LD_LIBRARY_PATH=${LD_LIBRARY_PATH:-\"(unset)\"}\"\necho \"[env] LD_PRELOAD(parent)=${LD_PRELOAD:-\"(unset)\"}\"\necho \"[env] shim.so=$([ -f \"$T/shim.so\" ] && ls -l \"$T/shim.so\" | awk '{print $5\" B\"}' || echo MISSING)\"\n\n# 真 hdc 候选（按序探测）：$HDC_BRIDGE_REAL 覆盖 → 系统 hnp SDK → brew\nhdc_candidates() {\n    [ -n \"$HDC_BRIDGE_REAL\" ] && echo \"$HDC_BRIDGE_REAL\"\n    for p in /data/service/hnp/hmos-clt.org/hmos-clt_*/sdk/default/openharmony/toolchains/hdc; do\n        [ -x \"$p\" ] && echo \"$p\"\n    done\n    [ -x \"$BREW_HDC\" ] && echo \"$BREW_HDC\"\n}\n\n# 0) 清理陈旧 socket / 残留 server（只在对应进程已不在时删，避免拆掉正在工作的服务端）\nif ! pgrep -f 'hdc [-]m' >/dev/null 2>&1; then\n    [ -S \"$SERVER_SOCK\" ] && rm -f \"$SERVER_SOCK\"\nfi\n# v3.1：socket 不在时，残留的 `hdc -m` 会让新 server 以为\"已有服务在跑\"直接退出（真机推测：\n# /data/hdc 日志里客户端 bind 报 ret:-13、server 又不出现）。这里把它和 .HDCServer.pid 一起清掉。\nif [ ! -S \"$SERVER_SOCK\" ]; then\n    if pgrep -f 'hdc [-]m' >/dev/null 2>&1; then\n        echo \"[0/3] 清理残留 hdc -m（socket 已不在）\"\n        pkill -f 'hdc [-]m' 2>/dev/null\n        sleep 0.5\n    fi\n    rm -f \"$H/.HDCServer.pid\" 2>/dev/null\n    rm -f \"$SERVER_SOCK\" 2>/dev/null\nfi\nif ! pgrep -f 'fakecred[.]py' >/dev/null 2>&1; then\n    [ -S \"$CRED_SOCK\" ] && rm -f \"$CRED_SOCK\"\nfi\n\n# 1) 恢复授权密钥（首次打通时由设备确认弹窗授权的 RSA 对 + 私钥 + 口令种子）\nif [ -f \"$D/keys/hdckey.pub\" ] && [ -f \"$D/keys/hdckey.key\" ]; then\n    mkdir -p \"$H/.harmony\"\n    cp \"$D/keys/hdckey.pub\" \"$H/.harmony/hdckey.pub\"\n    cp \"$D/keys/hdckey.key\" \"$H/.harmony/hdckey.key\"\n    [ -f \"$D/keys/hdckey\" ] && cp \"$D/keys/hdckey\" \"$H/.harmony/hdckey\"\n    chmod 666 \"$H/.harmony/hdckey.pub\" \"$H/.harmony/hdckey.key\" \"$H/.harmony/hdckey\" 2>/dev/null\n    echo \"[0/3] 授权密钥已恢复（免确认弹窗）\"\nfi\n\n# 2) 编译拦截库（幂等）\n#    brew clang 的 lld 靠 RUNPATH=$ORIGIN/../lib 找 libxml2，本机 musl 不展开 $ORIGIN\n#    ⇒ 显式把 lld 同级的 lib 目录塞进 LD_LIBRARY_PATH，否则链接失败、shim.so 编不出来。\nLLD=\"$(clang -print-prog-name=ld.lld 2>/dev/null)\"\nCLANG_LIBS=\"\"\ncase \"$LLD\" in\n    /*) [ -d \"$(dirname \"$LLD\")/../lib\" ] && CLANG_LIBS=\"$(dirname \"$LLD\")/../lib\";;\nesac\n# 2) 拦截库：优先用**随包预编译件**（$D/shim.so，2026-11-08 起随 HAP 分发，aarch64/musl）。\n#    干净设备没有 clang 时也能起桥；只有预编译件缺失/比源码旧时才回退现场编译。\nif [ -f \"$D/shim.so\" ] && { [ ! -f \"$T/shim.so\" ] || [ \"$D/shim.so\" -nt \"$T/shim.so\" ]; }; then\n    echo \"[1/3] 使用随包预编译 shim.so\"\n    if cp -f \"$D/shim.so\" \"$T/shim.so.new\" 2>/dev/null && chmod 755 \"$T/shim.so.new\" 2>/dev/null; then\n        mv -f \"$T/shim.so.new\" \"$T/shim.so\"\n    else\n        rm -f \"$T/shim.so.new\"\n        echo \"[1/3] ⚠ 预编译件拷贝失败，回退现场编译\"\n    fi\nfi\nif [ ! -f \"$T/shim.so\" ] || { [ ! -f \"$D/shim.so\" ] && [ \"$D/shim.c\" -nt \"$T/shim.so\" ]; }; then\n    echo \"[1/3] 编译 shim.so ...\"\n    rm -f \"$T/shim.so.new\"\n    RC=1\n    if [ -n \"$CLANG_LIBS\" ]; then\n        LD_LIBRARY_PATH=\"$CLANG_LIBS${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}\" \\\n            clang -shared -fPIC -O1 -o \"$T/shim.so.new\" \"$D/shim.c\" && RC=0\n    else\n        clang -shared -fPIC -O1 -o \"$T/shim.so.new\" \"$D/shim.c\" && RC=0\n    fi\n    if [ $RC -eq 0 ] && [ -f \"$T/shim.so.new\" ]; then\n        mv -f \"$T/shim.so.new\" \"$T/shim.so\"\n    else\n        rm -f \"$T/shim.so.new\"\n        # v3：编译失败但已有可用 shim.so 时**不拆桥**（以前直接 exit 1，会让自愈永久失败）\n        if [ -f \"$T/shim.so\" ]; then\n            echo \"[1/3] ⚠ 重新编译失败（clang 缺失/报错），沿用已有 shim.so\"\n        else\n            echo \"[1/3] ✗ 编译失败且没有可用 shim.so（需要 clang；见 README「shim 编译」）\"\n            exit 1\n        fi\n    fi\nelse\n    echo \"[1/3] shim.so 已就绪\"\nfi\necho \"$T/shim.so\" > \"$T/shim.path\"   # AGENTS.md 靠这个拿路径\n\n# 2.5) 【v3.2 预检】shim 到底有没有被注入？两个判决性读数，都无副作用\n#\n# 真机症状（2026-11-04 16:42 新 Whale）：`hdc -m` 自己写 .hdc/hdc.log：\n#   `SetUdsListen: bind uds addr fail! ret:-13`（EACCES）⇒ bind 没被改写到可写目录；\n# 且新 app 的 `$HOME/tmp/bindlog.txt` 从 15:40 起**一行都没新增** ⇒ shim 压根没被加载。\n# 旧 app（同 shim.so、同 hdc、同 setsid 写法）却正常 ⇒ 差别在\"新 app 的 spawn 环境\"。\n#   · maps 测试：LD_PRELOAD 一个真 ELF（sh）后看 /proc/self/maps 里有没有 shim.so ——\n#     有=注入成功；没有=注入被忽略（AT_SECURE / 路径不可见 / 加载器策略）。\n#   · bindlog 增量：注入后跑一次只读 `hdc list targets`，看 shim 有没有真的拦到 connect。\nREAL_FIRST=$(hdc_candidates | head -1)\nBL=\"$SHIMDIR/bindlog.txt\"\n[ -f \"$BL\" ] || : > \"$BL\"\nBL0=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\nif [ -n \"$REAL_FIRST\" ]; then\n    echo \"[preflight] shim=$T/shim.so ($(wc -c < \"$T/shim.so\" 2>/dev/null || echo 0) B) real=$REAL_FIRST\"\n    echo \"[preflight] maps 测试（LD_PRELOAD 注入 /system/bin/sh 后数 shim.so 出现次数）:\"\n    MAPS=$(LD_PRELOAD=\"$T/shim.so\" /system/bin/sh -c 'grep -c \"shim\\.so\" /proc/self/maps 2>/dev/null || echo 0' </dev/null 2>&1)\n    echo \"[preflight]   maps=$MAPS\" \n    echo \"[preflight] hdc -v (LD_PRELOAD):\"\n    LD_PRELOAD=\"$T/shim.so\" \"$REAL_FIRST\" -v </dev/null 2>&1 | head -3 | while IFS= read -r L; do echo \"[preflight]   $L\"; done\n    echo \"[preflight] bindlog 增量（注入后 hdc list targets）:\"\n    LD_PRELOAD=\"$T/shim.so\" \"$REAL_FIRST\" list targets </dev/null >/dev/null 2>&1\n    BL1=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n    echo \"[preflight]   bindlog $BL0 -> $BL1 (delta=$((BL1-BL0)))\"\n    echo \"[preflight] inline-assignment 传播（子 shell 里还能看到 LD_PRELOAD 吗）:\"\n    LD_PRELOAD=\"$T/shim.so\" /system/bin/sh -c 'echo \"[preflight]   sees=$LD_PRELOAD\"' </dev/null 2>&1\n    echo \"[preflight] export 方式注入 /system/bin/sh 后数 maps:\"\n    ( export LD_PRELOAD=\"$T/shim.so\"; /system/bin/sh -c 'grep -c \"shim\\.so\" /proc/self/maps 2>/dev/null || echo 0' </dev/null 2>&1 )\n    echo \"[preflight] 进程安全读数（NoNewPrivs/Seccomp/CapEff）:\"\n    ( export LD_PRELOAD=\"$T/shim.so\"; /system/bin/sh -c 'grep -E \"NoNewPrivs|Seccomp|CapEff\" /proc/self/status 2>/dev/null' </dev/null 2>&1 )\n    echo \"[preflight] 用自己的 bash（若在）做同一 maps 测试（排除 /system/bin/sh 因素）:\"\n    if [ -x \"$H/bin/bash\" ]; then\n        LD_PRELOAD=\"$T/shim.so\" \"$H/bin/bash\" -c 'grep -c \"shim\\.so\" /proc/self/maps 2>/dev/null || echo 0' </dev/null 2>&1\n    else\n        echo \"[preflight]   （无 $H/bin/bash）\"\n    fi\n    echo \"[preflight] 拷贝真 hdc 到应用私有目录后再注入（系统路径 vs 应用路径 的加载策略差异）:\"\n    if cp -f \"$REAL_FIRST\" \"$H/bin/hdc-copy\" 2>/dev/null; then\n        chmod 755 \"$H/bin/hdc-copy\" 2>/dev/null\n        echo \"[preflight]   copy=$H/bin/hdc-copy ($(wc -c < \"$H/bin/hdc-copy\" 2>/dev/null || echo 0) B)\"\n        echo \"[preflight]   copy -v (LD_PRELOAD):\"\n        LD_PRELOAD=\"$T/shim.so\" \"$H/bin/hdc-copy\" -v </dev/null 2>&1 | head -3\n        echo \"[preflight]   copy list targets (LD_PRELOAD) + bindlog 增量:\"\n        a=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n        LD_PRELOAD=\"$T/shim.so\" \"$H/bin/hdc-copy\" list targets </dev/null >/dev/null 2>&1\n        b=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n        echo \"[preflight]     bindlog delta=$((b-a))（>0 = 注入生效）\"\n        echo \"[preflight]   copy list targets (无注入) + bindlog 增量:\"\n        c=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n        \"$H/bin/hdc-copy\" list targets </dev/null >/dev/null 2>&1\n        d=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n        echo \"[preflight]     bindlog delta=$((d-c))（期望 0）\"\n    else\n        echo \"[preflight]   拷贝失败（$REAL_FIRST）\"\n    fi\n    echo \"[preflight] unset LD_LIBRARY_PATH 后 /system/bin/sh 的 maps:\"\n    ( unset LD_LIBRARY_PATH; LD_PRELOAD=\"$T/shim.so\" /system/bin/sh -c 'grep -c \"shim\\.so\" /proc/self/maps 2>/dev/null || echo 0' </dev/null 2>&1 )\n    echo \"[preflight] unset LD_LIBRARY_PATH 后注入 hdc list targets（bindlog 增量）:\"\n    u0=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n    ( unset LD_LIBRARY_PATH; LD_PRELOAD=\"$T/shim.so\" \"$REAL_FIRST\" list targets </dev/null >/dev/null 2>&1 )\n    u1=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n    echo \"[preflight]   bindlog delta=$((u1-u0))\"\n    echo \"[preflight] 进程/文件安全标签:\"\n    echo \"[preflight]   sh.attr=$(/system/bin/sh -c 'cat /proc/self/attr/current 2>/dev/null' </dev/null 2>&1)\"\n    echo \"[preflight]   shim.lsZ=$(ls -lZ \"$T/shim.so\" 2>/dev/null | head -1)\"\n    echo \"[preflight]   不同目录下的 shim 注入测试:\"\n    for d in \"$H/tmp\" \"$H/bin\" \"/data/local/tmp\"; do\n        cp -f \"$T/shim.so\" \"$d/shim-test.so\" 2>/dev/null || { echo \"[preflight]     $d: 拷贝失败\"; continue; }\n        chmod 755 \"$d/shim-test.so\" 2>/dev/null\n        m=$(LD_PRELOAD=\"$d/shim-test.so\" /system/bin/sh -c 'grep -c shim /proc/self/maps 2>/dev/null || echo 0' </dev/null 2>&1 | head -1)\n        echo \"[preflight]     $d -> maps=$m\"\n        rm -f \"$d/shim-test.so\" 2>/dev/null\n    done\n    echo \"[preflight] 对照：不带 LD_PRELOAD 的 hdc list targets:\"\n    \"$REAL_FIRST\" list targets </dev/null >/dev/null 2>&1\n    BL2=$(wc -c < \"$BL\" 2>/dev/null || echo 0)\n    echo \"[preflight]   bindlog $BL1 -> $BL2 (delta=$((BL2-BL1))，期望 0)\"\nfi\n\n# 3) 假凭据服务（幂等；socket 落在 $SHIMDIR，与 shim 映射一致）\nif [ -S \"$CRED_SOCK\" ] && kill -0 \"$(cat \"$T/cred.pid\" 2>/dev/null)\" 2>/dev/null; then\n    echo \"[2/3] fakecred 已运行\"\nelse\n    echo \"[2/3] 启动 fakecred ...\"\n    rm -f \"$CRED_SOCK\"\n    # 恢复 DECRYPT 口令（私钥解密用；存档于 keys/pwd.seed）\n    [ -s \"$SHIMDIR/credstate.txt\" ] || { [ -f \"$D/keys/pwd.seed\" ] && cp \"$D/keys/pwd.seed\" \"$SHIMDIR/credstate.txt\"; }\n    # setsid 必需：在 AI 工具调用（或任何\"命令结束即回收进程组\"的宿主）里，\n    # nohup 起的后台子进程会随进程组一起被杀 ⇒ 握手时凭据 socket 无监听\n    # （症状：hdc tconn 报 [Fail]Connect failed、bindlog 里 credential socket ret=-1）。\n    setsid python3 \"$D/fakecred.py\" </dev/null >/dev/null 2>&1 &\n    echo $! > \"$T/cred.pid\"\n    sleep 1\nfi\n\n# 4) hdc server（带注入，后台）\n#    逐个候选真 hdc 试：起 server → 等 socket 出现。只有能被 shim 注入 bind 的版本\n#    才建得出 socket（新版 brew hdc 会在 bind 处直接 EACCES 然后退出）。\nstart_server() {\n    for cand in $(hdc_candidates); do\n        [ -x \"$cand\" ] || continue\n        echo \"[3/3] 尝试真 hdc：$cand\"\n        rm -f \"$SERVER_SOCK\"\n        # v3.1：候选的 stdout/stderr 必须留证（原来 >/dev/null 2>&1 ⇒ 起不来完全没线索）；\n        # 并且 setsid 只是\"防宿主回收进程组\"的加固，缺失时回退 nohup/普通后台，不能让整段失效。\n        # v3.2：两种包装都试 —— `setsid` 只是\"防宿主回收进程组\"的加固；若某些环境里\n        # setsid 会丢掉 LD_PRELOAD（真机排查中要排除的可能），直起也要能成功。\n        for WRAP in setsid direct; do\n            echo \"[3/3]   wrapper=$WRAP\"\n            if [ \"$WRAP\" = \"setsid\" ] && ! command -v setsid >/dev/null 2>&1; then\n                echo \"[3/3]   setsid 不存在，跳过\"\n                continue\n            fi\n            if [ \"$WRAP\" = \"setsid\" ]; then\n                env -u LD_LIBRARY_PATH LD_PRELOAD=\"$T/shim.so\" setsid \"$cand\" -m </dev/null >>\"$T/server.log\" 2>&1 &\n            else\n                env -u LD_LIBRARY_PATH LD_PRELOAD=\"$T/shim.so\" \"$cand\" -m </dev/null >>\"$T/server.log\" 2>&1 &\n            fi\n            echo $! > \"$T/server.pid\"\n            i=0\n            while [ $i -lt 8 ]; do\n                [ -S \"$SERVER_SOCK\" ] && break\n                sleep 0.5; i=$((i+1))\n            done\n            if [ -S \"$SERVER_SOCK\" ]; then\n                echo \"$cand\" > \"$T/real.path\"\n                echo \"[3/3] hdc server 已启动（$cand，wrapper=$WRAP）\"\n                return 0\n            fi\n            echo \"[3/3]   $WRAP 起不来\"\n            pkill -f 'hdc [-]m' 2>/dev/null\n            sleep 0.3\n        done\n        i=0\n        while [ $i -lt 8 ]; do\n            [ -S \"$SERVER_SOCK\" ] && break\n            sleep 0.5; i=$((i+1))\n        done\n        if [ -S \"$SERVER_SOCK\" ]; then\n            echo \"$cand\" > \"$T/real.path\"\n            echo \"[3/3] hdc server 已启动（$(cat \"$T/real.path\")）\"\n            return 0\n        fi\n        echo \"[3/3] 该 hdc 起不来（setsid/直起都不行），换下一个\"\n        echo \"--- $cand 的输出尾部 ---\"\n        tail -8 \"$T/server.log\" 2>/dev/null | while IFS= read -r L; do echo \"[3/3]   $L\"; done\n        pkill -f 'hdc [-]m' 2>/dev/null\n        sleep 0.5\n    done\n    return 1\n}\n\nSERVER_OK=1\nif [ -S \"$SERVER_SOCK\" ]; then\n    echo \"[3/3] hdc server 已在运行\"\nelse\n    echo \"[3/3] 启动 hdc server（LD_PRELOAD 注入）...\"\n    if ! start_server; then\n        echo \"[3/3] 所有候选 hdc 都起不来：确认 /data/service/hnp 的 hdc 还在、并检查无线调试\"\n        echo \"[3/3] 先把 hdcb/hdc 包装更新到 v3（失败也更新，避免下次仍用旧包装盲 exec）\"\n        SERVER_OK=0\n    fi\nfi\n\n# 5) 安装/刷新 hdcb 与 hdc 转发器（PATH 首位目录，清数据后也能随本脚本恢复）\n#    注意：下面是单引号 heredoc（原样写出），@BRIDGE_DIR@ 之后用 sed 替换成绝对路径。\nHDCB=\"$H/bin/hdcb\"\nif ! grep -q \"hdcb-v5-20261104\" \"$HDCB\" 2>/dev/null; then\n    cat > \"$T/hdcb.new\" <<'HDCBEOF'\n#!/data/storage/el2/base/haps/entry/files/bin/ash\n# hdcb —— 经 hdc-bridge 的 hdc 包装（hdcb-v5-20261104；版本标记：bridge.sh 按它判断要不要重建）\n# 解释器用应用自带 ash 而非 /system/bin/sh：宿主进程带 libappspawn_helper.z.so，直接 exec\n# 系统二进制会让子进程丢 LD_PRELOAD（WhaleX 真机根因，2026-11-05）；经 app 自有 ash 中转则正常。\n#\n# 设计（2026-11-04 真机实测后重写）：\n#   · 端口自适应：无线调试端口每次开机/换网都会变，但系统把它写在 `persist.hdc.port`，\n#     app 上下文 `param get` 读得到 ⇒ 每次调用**现读**，不依赖过期缓存。\n#   · 有目标 → 直通（毫秒级）。\n#   · 没目标 → 确保 fakecred 在（冷启动握手必需）→ 现读端口 → tconn 一次 → 再验。\n#   · 还不行 → **一次**有界扫描（scanports，约 3s；只在兜底用）→ 逐个候选 tconn。\n#   · 全失败 → exit 3。**不反复扫描、不循环自愈、不重启 server**（避免留僵尸 hdc -m）。\nBR=\"$HOME/.hdc-bridge\"\nLOG=\"$HOME/tmp/hdcb-err.log\"\nmkdir -p \"$HOME/tmp\" 2>/dev/null\nREAL=\"$([ -s \"$BR/real.path\" ] && cat \"$BR/real.path\" 2>/dev/null)\"\nSHIM=\"$BR/shim.so\"\ntrim() { printf '%s' \"$1\" | tr -d ' \\t\\r\\n'; }\nhave_target() { \"$REAL\" list targets 2>>\"$LOG\" | grep -qE '127\\.0\\.0\\.1:[0-9]+'; }\nensure_fakecred() {\n    [ -S \"$HOME/tmp/hdcshim_hdc_credential.socket\" ] && return 0\n    [ -f \"$BR/src/fakecred.py\" ] || return 0\n    [ -s \"$HOME/tmp/credstate.txt\" ] || { [ -f \"$BR/src/keys/pwd.seed\" ] && cp \"$BR/src/keys/pwd.seed\" \"$HOME/tmp/credstate.txt\" 2>/dev/null; }\n    setsid python3 \"$BR/src/fakecred.py\" </dev/null >/dev/null 2>&1 &\n    sleep 1\n}\n{\n    echo \"=== $(date +%H:%M:%S) argv=[$*]\"\n} >> \"$LOG\" 2>/dev/null\n\n[ -x \"$REAL\" ] || { echo \"hdcb: 真 hdc 未知（$BR/real.path 缺失或不可执行）\" >&2; exit 3; }\n[ -f \"$SHIM\" ] || { echo \"hdcb: $BR/shim.so 缺失\" >&2; exit 3; }\nexport LD_PRELOAD=\"$SHIM\"\nunset LD_LIBRARY_PATH 2>/dev/null\n\n# 1) 有目标：直通\nhave_target && exec \"$REAL\" \"$@\"\n\n# 2) 冷启动：确保 fakecred（凭据握手）在，再现读端口\nensure_fakecred\nPORT=$(trim \"$(param get persist.hdc.port 2>/dev/null)\")\n[ -z \"$PORT\" ] && PORT=$(trim \"$(cat \"$BR/port.cache\" 2>/dev/null)\")\necho \"    port=[$PORT]\" >> \"$LOG\" 2>/dev/null\nif [ -n \"$PORT\" ]; then\n    \"$REAL\" tconn \"127.0.0.1:$PORT\" >>\"$LOG\" 2>&1\n    if have_target; then echo \"$PORT\" > \"$BR/port.cache\" 2>/dev/null; exec \"$REAL\" \"$@\"; fi\nfi\n\n# 3) 兜底：一次有界扫描 → 逐个候选 tconn\nSCAN=\"$BR/src/scanports.py\"\nif [ -f \"$SCAN\" ]; then\n    echo \"    fallback: scan once\" >> \"$LOG\" 2>/dev/null\n    CAND=$(timeout 8 python3 \"$SCAN\" 2>/dev/null)\n    for p in $CAND; do\n        case \"$p\" in\n            3[0-9][0-9][0-9][0-9]|4[0-9][0-9][0-9][0-9]|5[0-9][0-9][0-9][0-9]) ;;\n            *) continue ;;\n        esac\n        [ \"$p\" = \"$PORT\" ] && continue\n        \"$REAL\" tconn \"127.0.0.1:$p\" >>\"$LOG\" 2>&1\n        if have_target; then\n            echo \"$p\" > \"$BR/port.cache\" 2>/dev/null\n            exec \"$REAL\" \"$@\"\n        fi\n    done\nfi\n\necho \"hdcb: 没有可连目标（端口 ${PORT:-未知}）。请确认 开发者选项→无线调试 已开启；已做一次有界扫描后仍失败，不再重试（exit 3）。\" >&2\nexit 3\nHDCBEOF\n    sed \"s|@BRIDGE_DIR@|$D|g\" \"$T/hdcb.new\" > \"$HDCB\"\n    rm -f \"$T/hdcb.new\"\n    chmod +x \"$HDCB\"\n    echo \"[4/5] hdcb 包装命令已就绪（v5）\"\nelse\n    echo \"[4/5] hdcb 包装命令已存在\"\nfi\n\n# hdc 转发器：任何会话/脚本敲 hdc 也自动过桥（本地信息类命令直传）\nHDCFW=\"$H/bin/hdc\"\nif ! grep -q \"自动过桥-v5-20261104\" \"$HDCFW\" 2>/dev/null; then\n    cat > \"$T/hdc.new\" <<'HDCFWEOF'\n#!/data/storage/el2/base/haps/entry/files/bin/ash\n# hdc 自动过桥转发器（自动过桥-v5-20261104）：一律转 hdcb（端口现读 param、有界、不扫描为常态）\n# 解释器用应用自带 ash（同上 hdcb）：宿主直接 exec /system/bin/sh 会让子进程丢 LD_PRELOAD。\nif [ -x \"$HOME/bin/hdcb\" ]; then exec \"$HOME/bin/hdcb\" \"$@\"; fi\nREAL=\"$([ -s \"$HOME/.hdc-bridge/real.path\" ] && cat \"$HOME/.hdc-bridge/real.path\" 2>/dev/null)\"\ncase \"$1\" in\n  -v|version|--version|-h|--help|help) [ -x \"$REAL\" ] && exec \"$REAL\" \"$@\";;\nesac\necho \"[hdc] 缺少 $HOME/bin/hdcb（hdc-bridge 未部署）；请跑 bridge.sh\" >&2\nexit 3\nHDCFWEOF\n    cat \"$T/hdc.new\" > \"$HDCFW\"\n    rm -f \"$T/hdc.new\"\n    chmod +x \"$HDCFW\"\n    echo \"[5/5] hdc 转发器已就绪（敲 hdc 或 hdcb 都会自动起桥）\"\nelse\n    echo \"[5/5] hdc 转发器已存在\"\nfi\n\nif [ \"$SERVER_OK\" = \"1\" ]; then\n    echo \"[result] OK server=$SERVER_SOCK\"\nelse\n    echo \"[result] FAIL 原因见上面的 [env] 与 [3/3] 输出（server.log）\"\n    exit 1\nfi\necho\necho \"== 首选：直接用 hdcb（自动起桥+连本机+注入环境）==\"\necho \"hdcb shell id | hdcb list targets -v | hdcb hilog -x | hdcb install xxx.hap\"\necho\necho \"== 手动方式（了解原理用）==\"\necho \"export LD_PRELOAD=\\\"$T/shim.so\\\"\"\necho \"端口自适应：每次现读 persist.hdc.port（app 侧可读）；只在读不到时做一次约 3s 的有界扫描\"\necho \"真 hdc：$([ -s \"$T/real.path\" ] && cat \"$T/real.path\" || echo \"(未探测，请先跑本脚本)\")\"\necho \"hdc list targets -v                  # 期望：TCP Connected（端口自动发现）\"\n",
  "fakecred.py": "import socket, os, threading, binascii\n\n# v3(2026-11-04)：路径不再写死 —— 从 $HOME 推导（shim.c 的 SHIMDIR 就是 $HOME/tmp）。\n# 写死 /data/storage/el2/base/... 在别的包/别的工作目录下会静默写错地方（socket 建到\n# 不存在的目录 ⇒ 监听失败，但日志写不进去，表现为\"桥随机坏\"）。\n_HOME = os.environ.get(\"HOME\") or \"/data/storage/el2/base/haps/entry/files\"\n_TMP = os.path.join(_HOME, \"tmp\")\nP = os.path.join(_TMP, \"hdcshim_hdc_credential.socket\")\nLOG = os.path.join(_TMP, \"credlog.txt\")\nSTATE = os.path.join(_TMP, \"credstate.txt\")\nos.makedirs(_TMP, exist_ok=True)\n\ndef log(msg):\n    try: open(LOG,'a').write(msg)\n    except: pass\n\ndef load_state():\n    try:\n        return open(STATE,'rb').read()\n    except: return b\"\"\n\ndef save_state(d):\n    try: open(STATE,'wb').write(d)\n    except: pass\n\ndef handle(c):\n    try:\n        c.settimeout(5)\n        hdr = b\"\"\n        while len(hdr) < 8:\n            chunk = c.recv(8-len(hdr))\n            if not chunk: break\n            hdr += chunk\n        log(f\"conn: hdr={hdr!r}\\n\")\n        if len(hdr) < 8:\n            return\n        ver = hdr[0:1].decode('latin1')\n        method = hdr[1:4].decode('latin1')\n        try: ln = int(hdr[4:8].decode('latin1'))\n        except: ln = 0\n        body = b\"\"\n        while len(body) < ln:\n            chunk = c.recv(ln-len(body))\n            if not chunk: break\n            body += chunk\n        log(f\"  req ver={ver} method={method} len={ln} body={binascii.hexlify(body)[:60]}\\n\")\n        if method == \"001\":   # ENCRYPT: 记住口令，回 38 字节假密文\n            save_state(body)\n            fake = bytes(range(12)) + bytes([0xAA])*10 + bytes(range(16,32))\n            resp = b\"1\" + b\"001\" + b\"0038\" + fake\n            c.sendall(resp)\n            log(f\"  -> ENCRYPT resp 46B\\n\")\n        elif method == \"002\": # DECRYPT: 回存的口令\n            pwd = load_state() or b\"ABCDEFGHIJ\"\n            resp = b\"1\" + b\"002\" + b\"%04d\" % len(pwd) + pwd\n            c.sendall(resp)\n            log(f\"  -> DECRYPT resp {len(resp)}B\\n\")\n        else:\n            log(f\"  -> unknown method, no resp\\n\")\n    except Exception as e:\n        log(f\"  ERR {e}\\n\")\n    finally:\n        try: c.close()\n        except: pass\n\ntry: os.unlink(P)\nexcept: pass\ns = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\ns.bind(P); s.listen(8)\nos.chmod(P, 0o666)\nlog(\"=== fakecred2 listener up ===\\n\")\nwhile True:\n    conn,_ = s.accept()\n    threading.Thread(target=handle, args=(conn,), daemon=True).start()\n",
  "scanports.py": "#!/usr/bin/env python3\n\"\"\"扫描 127.0.0.1 上所有 LISTEN TCP 端口（非阻塞并发），输出空格分隔的端口列表。\n\n用途：hdc-bridge 的兜底端口发现（应用沙箱读不到 /proc/net/tcp）。\n本机回环上 connect 结果几乎瞬时返回（RST/成功），非阻塞 connect_ex + select 收尾，\n全量扫描 1024-65535 约 2~5 秒。只在 param/缓存/已知端口全部失败时才会被调用。\n\"\"\"\nimport select\nimport socket\nimport sys\nimport time\n\nHOST = \"127.0.0.1\"\nSTART, END = 1024, 65536\nBATCH = 400  # 内嵌 Python 的 select() fd 上限 1024，批次须留足余量\nWAIT = 0.20\n\n\ndef scan():\n    found = []\n    for base in range(START, END, BATCH):\n        pending = {}\n        for port in range(base, min(base + BATCH, END)):\n            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n            s.setblocking(False)\n            try:\n                err = s.connect_ex((HOST, port))\n            except OSError:\n                s.close()\n                continue\n            if err == 0:  # 立即连接成功 = 端口在监听\n                found.append(port)\n                s.close()\n                continue\n            if err == 115:  # EINPROGRESS\n                pending[s] = port\n            else:\n                s.close()\n        # 收尾：等在途连接最多 WAIT 秒\n        deadline = time.time() + WAIT\n        while pending and time.time() < deadline:\n            try:\n                _r, w, x = select.select([], list(pending), list(pending), 0.05)\n            except OSError:\n                break\n            for s in x:\n                try:\n                    if s.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR) == 0:\n                        found.append(pending[s])\n                except OSError:\n                    pass\n                s.close()\n                del pending[s]\n            for s in w:\n                try:\n                    if s.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR) == 0:\n                        found.append(pending[s])\n                except OSError:\n                    pass\n                s.close()\n                del pending[s]\n        for s in list(pending):\n            s.close()\n            del pending[s]\n    found.sort()\n    return found\n\n\nif __name__ == \"__main__\":\n    print(\" \".join(map(str, scan())))\n",
  "shim.c": "#define _GNU_SOURCE\n#include <sys/types.h>\n#include <sys/socket.h>\n#include <sys/un.h>\n#include <sys/stat.h>\n#include <dlfcn.h>\n#include <stdarg.h>\n#include <string.h>\n#include <stdio.h>\n#include <errno.h>\n#include <unistd.h>\n\n#define SHIMDIR \"/data/storage/el2/base/haps/entry/files/tmp\"\n#define SELF    \"/data/storage/el2/base/haps/entry/files\"\n#define LOGFILE SHIMDIR \"/bindlog.txt\"\n\nstatic void logmsg(const char *fmt, ...) {\n    FILE *f = fopen(LOGFILE, \"a\");\n    if (!f) return;\n    va_list ap; va_start(ap, fmt); vfprintf(f, fmt, ap); va_end(ap);\n    fclose(f);\n}\n\n/* 把系统侧 unix socket 路径映射到可写目录；路径其它用法同样映射 */\nstatic int map_path(const char *p, char *out, size_t outsz) {\n    if (!p) return 0;\n    if (strncmp(p, \"/data/\", 6) && strncmp(p, \"/dev/\", 5) && strncmp(p, \"/system/\", 8)) return 0;\n    if (!strncmp(p, SELF, sizeof(SELF)-1)) return 0;\n    const char *base = strrchr(p, '/'); base = base ? base+1 : p;\n    if (!*base) base = \"anon\";\n    snprintf(out, outsz, \"%s/hdcshim_%s\", SHIMDIR, base);\n    return 1;\n}\n\ntypedef int (*bind_fn)(int, const struct sockaddr *, socklen_t);\ntypedef int (*connect_fn)(int, const struct sockaddr *, socklen_t);\ntypedef int (*chmod_fn)(const char *, mode_t);\ntypedef int (*stat_fn)(const char *, struct stat *);\ntypedef int (*unlink_fn)(const char *);\ntypedef int (*access_fn)(const char *, int);\n\nint bind(int fd, const struct sockaddr *addr, socklen_t len) {\n    static bind_fn real; if (!real) real = (bind_fn)dlsym(RTLD_NEXT, \"bind\");\n    if (addr && addr->sa_family == AF_UNIX) {\n        char np[128];\n        if (map_path(((struct sockaddr_un*)addr)->sun_path, np, sizeof(np))) {\n            struct sockaddr_un nu; memset(&nu, 0, sizeof(nu));\n            nu.sun_family = AF_UNIX; strncpy(nu.sun_path, np, sizeof(nu.sun_path)-1);\n            unlink(np);\n            int r = real(fd, (struct sockaddr *)&nu, sizeof(nu));\n            logmsg(\"bind(%s)->%s ret=%d\\n\", ((struct sockaddr_un*)addr)->sun_path, np, r);\n            return r;\n        }\n    }\n    return real(fd, addr, len);\n}\n\nint connect(int fd, const struct sockaddr *addr, socklen_t len) {\n    static connect_fn real; if (!real) real = (connect_fn)dlsym(RTLD_NEXT, \"connect\");\n    if (addr && addr->sa_family == AF_UNIX) {\n        char np[128];\n        if (map_path(((struct sockaddr_un*)addr)->sun_path, np, sizeof(np))) {\n            struct sockaddr_un nu; memset(&nu, 0, sizeof(nu));\n            nu.sun_family = AF_UNIX; strncpy(nu.sun_path, np, sizeof(nu.sun_path)-1);\n            int r = real(fd, (struct sockaddr *)&nu, sizeof(nu));\n            logmsg(\"connect(%s)->%s ret=%d\\n\", ((struct sockaddr_un*)addr)->sun_path, np, r);\n            return r;\n        }\n    }\n    return real(fd, addr, len);\n}\n\nint chmod(const char *path, mode_t mode) {\n    static chmod_fn real; if (!real) real = (chmod_fn)dlsym(RTLD_NEXT, \"chmod\");\n    char np[128];\n    if (map_path(path, np, sizeof(np))) {\n        int r = real(np, mode);\n        logmsg(\"chmod(%s)->%s ret=%d errno=%d\\n\", path, np, r, errno);\n        return r;\n    }\n    return real(path, mode);\n}\n\nint stat(const char *path, struct stat *st) {\n    static stat_fn real; if (!real) real = (stat_fn)dlsym(RTLD_NEXT, \"stat\");\n    char np[128];\n    if (map_path(path, np, sizeof(np))) {\n        int r = real(np, st);\n        logmsg(\"stat(%s)->%s ret=%d errno=%d\\n\", path, np, r, errno);\n        return r;\n    }\n    return real(path, st);\n}\n\nint lstat(const char *path, struct stat *st) {\n    static stat_fn real; if (!real) real = (stat_fn)dlsym(RTLD_NEXT, \"lstat\");\n    char np[128];\n    if (map_path(path, np, sizeof(np))) {\n        int r = real(np, st);\n        logmsg(\"lstat(%s)->%s ret=%d errno=%d\\n\", path, np, r, errno);\n        return r;\n    }\n    return real(path, st);\n}\n\nint unlink(const char *path) {\n    static unlink_fn real; if (!real) real = (unlink_fn)dlsym(RTLD_NEXT, \"unlink\");\n    char np[128];\n    if (map_path(path, np, sizeof(np))) {\n        int r = real(np);\n        logmsg(\"unlink(%s)->%s ret=%d\\n\", path, np, r);\n        return r;\n    }\n    return real(path);\n}\n\nint access(const char *path, int mode) {\n    static access_fn real; if (!real) real = (access_fn)dlsym(RTLD_NEXT, \"access\");\n    char np[128];\n    if (map_path(path, np, sizeof(np))) {\n        int r = real(np, mode);\n        logmsg(\"access(%s)->%s ret=%d errno=%d\\n\", path, np, r, errno);\n        return r;\n    }\n    return real(path, mode);\n}\n",
  "shim.so": { encoding: 'base64', data: '' }
};
